import React, { useState, useEffect } from "react";
import axios from "axios";
import { Toast } from "primereact/toast";
import { Dialog } from "primereact/dialog";
import { Button } from "primereact/button";

const VetAppointments = () => {
  const [appointments, setAppointments] = useState([]);
  const [selectedAppointment, setSelectedAppointment] = useState(null);
  const [editDialog, setEditDialog] = useState(false);
  const toast = React.useRef(null);

  const fetchAppointments = async () => {
    try {
      const response = await axios.get("http://localhost:5000/api/appointments");
      console.log("Fetched appointments:", response.data);
      setAppointments(response.data);
    } catch (error) {
      console.error("Error fetching appointments:", error);
      toast.current.show({ severity: "error", summary: "Error", detail: "Failed to fetch appointments." });
    }
  };

  useEffect(() => {
    fetchAppointments();
  }, []);

  const handleEdit = (appointment) => {
    setSelectedAppointment(appointment);
    setEditDialog(true);
  };

  const handleUpdate = async () => {
    // Update logic here
    // After updating, you can call fetchAppointments() to refresh the data
  };

  return (
    <div>
      <Toast ref={toast} position="bottom-right" />
      <h2>Pending Appointments</h2>
      <ul>
        {appointments.map((appointment) => (
          <li key={appointment._id}>
            {appointment.ownerName} - {appointment.petDetails}
            <Button label="Edit" onClick={() => handleEdit(appointment)} />
          </li>
        ))}
      </ul>

      {/* Edit Dialog */}
      <Dialog visible={editDialog} header="Edit Appointment" onHide={() => setEditDialog(false)}>
        {selectedAppointment && (
          <div>
            <label>Status</label>
            <select
              value={selectedAppointment.status}
              onChange={(e) => setSelectedAppointment({ ...selectedAppointment, status: e.target.value })}
            >
              <option value="Confirmed">Confirmed</option>
              <option value="Cancelled">Cancelled</option>
              <option value="Completed">Completed</option>
            </select>
          </div>
        )}
        <div>
          <Button label="Cancel" onClick={() => setEditDialog(false)} />
          <Button label="Update" onClick={handleUpdate} />
        </div>
      </Dialog>
    </div>
  );
};

export default VetAppointments;
